function serviceQuickActions(s){if(revertibleActivation(s)&&s.status==='completed')return[['revert_activation','Revertir activado']];if(!s||LEGACY_STATUS.has(s.status)||['completed','cancelled'].includes(s.status))return[];if(s.driver_activated)return[['finalize','Finalizar'],['revert_activation','Revertir activado']];const status=normalizedStatus(s),signed=!!s.remito_id&&['submitted','approved'].includes(s.document_status);/* Tercerizada: no hay chofer ni móvil propios. «Asignar» lo asigna al tercerizado elegido; también se puede finalizar directo. */if(s.logistics_type==='third_party'&&!signed){if(status==='pending')return[['assign_outsourced','Asignar'],['finalize','Finalizar'],['annul','Anular']];if(status==='assigned')return[['unassign','Quitar asignación'],['finalize','Finalizar'],['annul','Anular']];}if(status==='pending')return[['assign','Asignar'],['activate','Activado'],['annul','Anular']];if(status==='assigned')return signed?[['finalize','Finalizar']]:[['reassign','Reasignar'],['unassign','Quitar asignación'],['arrive','Arribado'],['activate','Activado'],['finalize','Finalizar'],['annul','Anular']];if(status==='at_origin')return signed?[['finalize','Finalizar']]:[['unarrive','Desarribar'],['activate','Activado'],['finalize','Finalizar'],['annul','Anular']];return[]}
/* Asignar a un tercerizado: se elige quién lo hace y, si su tarifa es por localidad, la localidad. Nunca se muestran importes. */
