function outsourcedFields(){return`<div class="osl-assignment-fields osl-terc-fields"><label><span>Tercerizado</span><select id="osl-terc-provider"><option value="">Cargando…</option></select></label><label id="osl-terc-loc-wrap" hidden><span>Localidad</span><select id="osl-terc-locality"><option value="">Elegí la localidad</option></select></label></div><p class="osl-terc-note" id="osl-terc-note" hidden></p>`}
const tercOk=(p,s)=>!!p?.has_rate&&(p.concepts||[]).map(String).includes(String(s?.primary_concept_id||''));
