 const [list,cur]=await Promise.all([db().rpc('list_outsourced_providers_for_service_v1',{p_date:arDate(s.scheduled_for)}),db().rpc('get_outsourced_service_cost_v1',{p_service_id:s.service_id})]);
 if(!sel.isConnected)return;if(list.error){delete sel.dataset.loaded;sel.innerHTML='<option value="">No se pudieron cargar</option>';return showAssignmentError(m,list.error.message||'No se pudieron cargar los tercerizados.')}
 const rows=list.data||[];state.tercProviders=rows;const note=m.querySelector('#osl-terc-note');
 sel.innerHTML='<option value="">Elegí el tercerizado</option>'+rows.map(p=>`<option value="${esc(p.provider_id)}" ${tercOk(p,s)?'':'disabled'}>${esc(p.display_name)}${tercOk(p,s)?'':p.has_rate?' · su tarifa no incluye este servicio':' · sin tarifa'}</option>`).join('');
