 if(note){const msg=!rows.length?'No hay tercerizados cargados. Se cargan en Configuración › Tercerizados.':!rows.some(p=>tercOk(p,s))?'Ningún tercerizado tiene tarifa para este tipo de servicio en esta fecha. Se carga en Configuración › Tercerizados › Tarifas.':'';note.hidden=!msg;note.textContent=msg;}
