function closeQuickMenu(){const menu=state.quickMenu;if(menu){menu.hidden=true;menu.innerHTML=''}state.quickMenuAnchor?.setAttribute('aria-expanded','false');state.quickMenuAnchor=null;state.quickMenuServiceId=null}
function suggestedQuickAction(s,actions){
  if(!canTransition()||!s||['completed','cancelled'].includes(s.status))return '';
  const status=normalizedStatus(s),preferred=s.driver_activated||status==='at_origin'?['finalize']:status==='pending'?['assign','assign_outsourced']:status==='assigned'?['arrive','finalize']:[];
  return preferred.find(key=>actions.some(([action])=>action===key))||'';
}
function openQuickStatusMenu(id,anchor){
  const s=service(id),actions=quickActions(s);if(!actions.length)return;
  const menu=ensureQuickMenu(),rect=anchor.getBoundingClientRect(),suggested=suggestedQuickAction(s,actions);
  state.quickMenuAnchor?.setAttribute('aria-expanded','false');state.quickMenuAnchor=anchor;anchor.setAttribute('aria-expanded','true');
  state.quickMenuServiceId=id;menu.setAttribute('role','menu');
  menu.innerHTML='<div class="osl-quick-head">Cambiar estado</div>'+actions.map(([action,label])=>`${action==='annul'&&actions.length>1?'<hr>':''}<button type="button" role="menuitem" data-osl-quick-action="${action}"${action===suggested?' class="is-next" data-osl-suggested="true"':''}>${ico(QUICK_ICON[action]||'chevron-right')}${esc(action==='arrive'?'Arribar':label)}</button>`).join('');
  menu.hidden=false;
  const width=menu.offsetWidth,height=menu.offsetHeight;
  menu.style.left=`${Math.max(8,Math.min(window.innerWidth-width-8,rect.left))}px`;
  menu.style.top=`${Math.max(8,Math.min(window.innerHeight-height-8,rect.bottom+5))}px`;
  requestAnimationFrame(()=>(menu.querySelector('.is-next')||menu.querySelector('button'))?.focus());
}
function runQuickAction(action,id){const readOnly=!canTransition(),s=service(id);closeQuickMenu();if(!quickActions(s).some(([key])=>key===action))return notify('El servicio cambió. Volvé a abrir el menú de estado.','warning');if(action==='assign_outsourced')return openOutsourcedAssign(id,readOnly);if(action==='assign'||action==='reassign')return openAssignment(id,readOnly);if(action==='finalize')return openFinalize(id,readOnly);if(action==='arrive')return openArrival(id,readOnly);if(action==='activate')return openActivation(id,readOnly);if(action==='revert_activation')return openRevertActivation(id,readOnly);if(action==='unarrive'||action==='unassign')return openRevert(action,id,readOnly);if(action==='annul')return openAnnul(id,readOnly);}
function onDocumentClickCapture(e){const nav=e.target.closest?.('.nav-item');if(nav&&state.modal&&!state.modal.hidden){close(false);return}const actionButton=e.target.closest?.('.osl-quick-status-menu [data-osl-quick-action]');if(actionButton){e.preventDefault();e.stopPropagation();const id=state.quickMenuServiceId,action=actionButton.dataset.oslQuickAction;if(id)runQuickAction(action,id);return}const status=e.target.closest?.('#screen-operaciones .col-status .os-status');if(status){const row=status.closest('tr[data-service-id]'),id=row?.dataset?.serviceId,s=id?service(id):null;if(quickActions(s).length){e.preventDefault();e.stopPropagation();if(state.quickMenuServiceId===id&&!state.quickMenu?.hidden)closeQuickMenu();else openQuickStatusMenu(id,status);return}}if(!e.target.closest?.('.osl-quick-status-menu'))closeQuickMenu()}
const EVENT_ICONS={created:'plus',assignment:'truck',reassigned:'truck',status_change:'refresh-cw',arrived:'map-pin',finalized:'circle-check',annulled:'circle-x',service_edit:'pencil'};
function eventText(e){const type=EVENT_LABELS[e.event_type]||e.event_type||'Evento',from=STATUS[e.from_status]||e.from_status,to=STATUS[e.to_status]||e.to_status;if(e.event_type==='status_change'&&from&&to)return`${from} → ${to}`;return e.notes||type}
function assignmentText(a){const resource=[a.driver_name||'Chofer',a.truck_label||'Móvil'].join(' · ');return a.released_at?`${resource} · liberado ${date(a.released_at)}`:resource}
async function renderHistory(id){const slot=document.getElementById('osv4-lifecycle-slot');if(!slot||!id)return;slot.hidden=false;slot.innerHTML='<div class="osl-empty">Cargando historial del servicio…</div>';try{const {data,error}=await db().rpc('get_operator_service_history_v2',{p_service_id:id});if(error)throw error;const events=Array.isArray(data?.events)?data.events:[],assignments=Array.isArray(data?.assignments)?data.assignments:[];slot.innerHTML=`<section class="osl-history"><div class="osl-history-head"><span>Estado actual</span><b>${esc(STATUS[data?.status]||data?.status||'')}</b></div>${events.length?`<ol class="osl-timeline">${events.map(e=>`<li data-type="${esc(e.event_type||'')}"><span class="osl-timeline-dot">${ico(EVENT_ICONS[e.event_type]||'clock','ax-icon-sm')}</span><div><b>${esc(eventText(e))}</b><small>${esc(e.created_by_name||'Sistema')} · ${esc(date(e.created_at))}</small></div></li>`).join('')}</ol>`:'<div class="osl-empty">Todavía no hay eventos registrados.</div>'}${assignments.length?`<details class="osl-assignments-box"><summary>Asignaciones <em>${assignments.length}</em>${ico('chevron-down','osl-chevron')}</summary><div class="osl-assignments">${assignments.map(a=>`<div><b>${ico('truck','ax-icon-sm')}${esc(a.driver_name||'Chofer')} · ${esc(a.truck_label||'Móvil')}</b><small>${esc(date(a.assigned_at))}${a.released_at?` → ${esc(date(a.released_at))}`:' · vigente'}</small></div>`).join('')}</div></details>`:''}</section>`}catch(e){slot.innerHTML=`<div class="osl-empty">${esc(e.message||'No se pudo cargar el historial.')}</div>`}}
function currentAssignmentKey(){const d=O()?.S?.wizard?.data||{};return`${d.assigned_driver_id||''}|${d.assigned_truck_id||''}`}
function confirmAssignmentChange(message){finishAssignmentConfirmation(false);return new Promise(resolve=>{const host=document.querySelector('.osv4-reactive .assignment-grid');if(!host){notify('No se pudo mostrar la confirmación de reasignación dentro del servicio.','error');resolve(false);return;}const lines=String(message||'').split(/\n+/).map(x=>x.trim()).filter(Boolean),card=document.createElement('div'),key=currentAssignmentKey();card.className='osl-assignment-inline';card.innerHTML=`<div class="osl-assignment-inline-copy"><b>${esc(lines[0]||'Confirmar cambio de asignación')}</b>${lines.slice(1).map(line=>`<span>${esc(line)}</span>`).join('')}</div><div class="osl-assignment-inline-actions"><button type="button" data-osl-assignment-cancel>Cancelar</button><button type="button" class="primary" data-osl-assignment-confirm>Confirmar cambio</button></div>`;host.insertAdjacentElement('afterend',card);state.assignmentResolver=resolve;state.assignmentCard=card;state.assignmentKey=key;card.querySelector('[data-osl-assignment-cancel]').addEventListener('click',()=>finishAssignmentConfirmation(false));card.querySelector('[data-osl-assignment-confirm]').addEventListener('click',()=>{if(currentAssignmentKey()!==state.assignmentKey){notify('La asignación cambió. Revisá Chofer y Móvil y volvé a confirmar.','error');finishAssignmentConfirmation(false);return;}startAssignmentSaving()})})}
/* Confirmar no cierra la tarjeta: queda en "Guardando…" hasta que el guardado del servicio informe el resultado con settleAssignmentConfirmation. */
function startAssignmentSaving(){const card=state.assignmentCard,resolve=state.assignmentResolver;state.assignmentResolver=null;state.assignmentSaving=true;if(card){card.classList.remove('is-error');card.querySelector('.osl-assignment-inline-error')?.remove();for(const b of card.querySelectorAll('button'))b.disabled=true;const confirm=card.querySelector('[data-osl-assignment-confirm]');if(confirm){confirm.hidden=false;confirm.textContent='Guardando…'}}if(resolve)resolve(true)}
function settleAssignmentConfirmation(message=null){const card=state.assignmentCard;if(!card||!state.assignmentSaving)return;state.assignmentSaving=false;if(!message){finishAssignmentConfirmation(false);return}if(!card.isConnected)document.querySelector('.osv4-reactive .assignment-grid')?.insertAdjacentElement('afterend',card);card.classList.add('is-error');let box=card.querySelector('.osl-assignment-inline-error');if(!box){box=document.createElement('span');box.className='osl-assignment-inline-error';box.setAttribute('role','alert');card.querySelector('.osl-assignment-inline-copy')?.appendChild(box)}box.textContent=message;const cancel=card.querySelector('[data-osl-assignment-cancel]'),confirm=card.querySelector('[data-osl-assignment-confirm]');if(cancel){cancel.disabled=false;cancel.textContent='Cerrar'}if(confirm)confirm.hidden=true}
function onWorkspaceOpened(e){if(state.modal&&!state.modal.hidden)close(false);finishAssignmentConfirmation(false);closeQuickMenu();const {serviceId,mode}=e.detail||{};if(serviceId&&['view','edit'].includes(mode))setTimeout(()=>renderHistory(serviceId),0)}
function syncQuickStatusAvailability(){document.body?.classList.toggle('osl-quick-status-enabled',!!O()?.canRead?.());for(const el of document.querySelectorAll('#screen-operaciones .col-status .os-status')){const s=service(el.closest('tr')?.dataset.serviceId);if(!quickActions(s).length)continue;el.setAttribute('role','button');el.tabIndex=0;el.setAttribute('aria-haspopup','menu');el.setAttribute('aria-expanded','false');el.setAttribute('aria-label',`${el.textContent.trim()}: cambiar estado`);}}
document.addEventListener('auxilios:services-rendered',syncQuickStatusAvailability);
document.addEventListener('keydown',event=>{const status=event.target.closest?.('#screen-operaciones .col-status .os-status[role="button"]');if(status&&['Enter',' '].includes(event.key)){event.preventDefault();status.click();}});
function init(){injectCss();ensureModal();ensureQuickMenu();syncQuickStatusAvailability();window.addEventListener('auxilios:service-workspace-opened',onWorkspaceOpened);window.addEventListener('popstate',()=>close(false));window.addEventListener('hashchange',()=>close(false));window.addEventListener('resize',closeQuickMenu);window.addEventListener('scroll',closeQuickMenu,true);document.addEventListener('click',onDocumentClickCapture,true);const w=O()?.S?.wizard;if(w?.serviceId)renderHistory(w.serviceId)}
const api={quickActions,openActivation,openActivatedFinalize,openRevertActivation,ARRIVAL_REASONS,ANNUL_REASONS,STATUS,openArrival,openFinalize,openAnnul,openAssignment,renderHistory,confirmAction,confirmAssignmentChange,settleAssignmentConfirmation,close};
window.OperatorServiceLifecycleV2=api;
Object.assign(window,{marcarArribadoManual:openArrival,finalizarServicioOperador:openFinalize,anularServicioOperador:openAnnul,asignarServicioRapido:openAssignment,cerrarModalLifecycleServicio:close});
document.readyState==='loading'?document.addEventListener('DOMContentLoaded',init,{once:true}):init();
